// Configuración de Research por marca. Para agregar una marca o cliente, agrega un objeto.
// competidores: nombres comerciales tal como aparecen en la Biblioteca de Anuncios de Meta.
// noticias: búsquedas de la semana (Tavily). keywords: palabras a medir (DataForSEO, México).
const semana = $now.setZone('America/Mexico_City').toFormat("kkkk-'W'WW");
const marcas = [
  {
    marca: 'marca-a',
    nombre: 'Marca A',
    competidores: ['Competidor 1', 'Competidor 2', 'Competidor 3'],
    noticias: ['tendencias de la industria México', 'regulación de la industria México'],
    keywords: ['producto principal', 'producto principal precio', 'mejor producto principal México'],
  },
  {
    marca: 'marca-b',
    nombre: 'Marca B',
    competidores: ['Competidor 1', 'Competidor 2'],
    noticias: ['tendencias de la industria B México'],
    keywords: ['servicio principal', 'servicio principal para empresas'],
  },
];
return marcas.map(m => ({ json: { ...m, semana } }));

const m = $('Investigar marca').first().json;
// Corta por caracteres completos (no parte emojis) y quita surrogates sueltos, que rompen el JSON.
const limpio = s => String(s || '').replace(/[\uD800-\uDBFF](?![\uDC00-\uDFFF])|(?<![\uD800-\uDBFF])[\uDC00-\uDFFF]/g, '');
const corto = (s, n) => Array.from(limpio(s).replace(/\s+/g, ' ').trim()).slice(0, n).join('');
const sinAcentos = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
const noticias = [];
const vistas = new Set();
for (const it of $('Tavily: noticias').all()) {
  for (const r of (it.json.results || [])) {
    if (!r.url || vistas.has(r.url)) continue;
    vistas.add(r.url);
    noticias.push({ titulo: corto(r.title, 160), url: r.url, fecha: r.published_date || '', extracto: corto(r.content, 300) });
  }
}
// Solo anuncios de la competencia. Nombres cortos solo cuentan si son la página; términos largos
// también cuentan si aparecen como palabra completa en el texto.
const escapar = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const terminos = m.competidores.map(c => { const t = sinAcentos(c); return { re: new RegExp('(^|[^a-z0-9])' + escapar(t) + '($|[^a-z0-9])'), enTexto: t.length > 6 || t.includes(' ') }; });
const plantilla = t => !t || /\{\{.*\}\}/.test(t);
const anuncios = [];
const errores = [];
for (const it of $('Apify: anuncios de competencia').all()) {
  const a = it.json;
  if (!a) continue;
  if (a.error) { errores.push('Apify: ' + (a.error.message || a.error.type || a.error)); continue; }
  const snap = a.snapshot || {};
  const pagina = a.pageName || snap.pageName || a.page_name || '';
  const card = (snap.cards && snap.cards[0]) || {};
  let texto = snap.body && snap.body.text;
  if (plantilla(texto)) texto = [card.title, card.body].filter(t => t && !plantilla(t)).join(' · ');
  if (!texto && !plantilla(snap.title)) texto = snap.title;
  const id = a.adArchiveID || a.adArchiveId || a.ad_archive_id || '';
  if (!pagina || !id) continue;
  const p = sinAcentos(pagina), tx = sinAcentos(texto);
  if (!terminos.some(x => x.re.test(p) || (x.enTexto && x.re.test(tx)))) continue;
  anuncios.push({ pagina, inicio: (a.startDateFormatted || a.start_date_formatted || '').slice(0, 10), texto: corto(texto, 300), destino: card.linkUrl || snap.linkUrl || '', url: 'https://www.facebook.com/ads/library/?id=' + id });
}
const d = $('DataForSEO: volumen de keywords').first().json;
const res = (d.tasks && d.tasks[0] && d.tasks[0].result) || [];
const keywords = res.map(k => ({ keyword: k.keyword, volumen: k.search_volume, cpc: k.cpc, competencia: k.competition }));
if (d.status_code && d.status_code !== 20000) errores.push('DataForSEO: ' + d.status_message);
return [{ json: { marca: m.marca, nombre: m.nombre, semana: m.semana, datos: { noticias, anuncios, keywords }, errores } }];

const r = $('GPT: hallazgos').first().json;
const j = $('Juntar datos').first().json;
const fecha = $now.setZone('America/Mexico_City').toFormat('yyyy-MM-dd');
return r.hallazgos.map(h => ({ json: { fecha, semana: j.semana, marca: r.marca, tipo: h.tipo, hallazgo: h.hallazgo, fuente: h.fuente, accion: h.accion, confianza: h.confianza } }));

const r = $('GPT: hallazgos').first().json;
const vol = {};
for (const k of $('Juntar datos').first().json.datos.keywords) vol[String(k.keyword).toLowerCase()] = k;
const fecha = $now.setZone('America/Mexico_City').toFormat('yyyy-MM-dd');
return r.keywords_nuevas.map(k => ({ json: { fecha, marca: r.marca, keyword: k.keyword, intencion: k.intencion, prioridad: k.prioridad, volumen: (vol[k.keyword] || {}).volumen ?? '', cpc: (vol[k.keyword] || {}).cpc ?? '', estado: 'nueva' } }));
